7:
8:import React from 'react'
9:import PropTypes from 'prop-types'
10:import {Link as RouteLink} from 'react-router-dom'
11:import {useIntl} from 'react-intl'
12:
13:// Components
14:import {
15:    Breadcrumb as ChakraBreadcrumb,
16:    BreadcrumbItem as ChakraBreadcrumbItem,
17:    BreadcrumbLink as ChakraBreadcrumbLink,
18:    // Hooks
19:    useStyleConfig
20:} from '@salesforce/retail-react-app/app/components/shared/ui'
21:
22:// Icons
23:import {ChevronRightIcon} from '@salesforce/retail-react-app/app/components/icons'
24:
25:// Others
26:import {categoryUrlBuilder} from '@salesforce/retail-react-app/app/utils/url'
27:
28:/**
29: * A simplification of the Chakra `Breadcrumb` component for our project needs. Given
30: * a list of categories, display a breadcrumb and it's items.
31: */
32:const Breadcrumb = ({categories, ...rest}) => {
33:    const intl = useIntl()
34:    const styles = useStyleConfig('Breadcrumb')
35:
36:    return (
37:        <ChakraBreadcrumb
38:            className="sf-breadcrumb"
39:            sx={styles.container}
40:            separator={<ChevronRightIcon {...styles.icon} aria-hidden="true" />}
41:            {...rest}
42:        >
43:            {categories.map((category) => (
44:                <ChakraBreadcrumbItem key={category.id} data-testid="sf-crumb-item">
45:                    <ChakraBreadcrumbLink
46:                        as={RouteLink}
47:                        to={categoryUrlBuilder(category, intl.locale)}
48:                        sx={styles.link}
49:                    >
50:                        {category.name}
51:                    </ChakraBreadcrumbLink>
52:                </ChakraBreadcrumbItem>
53:            ))}
54:        </ChakraBreadcrumb>
55:    )
56:}
57:
58:Breadcrumb.displayName = 'Breadcrumb'
59:
60:Breadcrumb.propTypes = {
61:    /**
62:     * The categories to be displayed in this breadcrumb.
63:     */
64:    categories: PropTypes.array
65:}
66:
67:export default Breadcrumb

